import { Routes } from '@angular/router';
import { authGuard, roleGuard } from './core/guards/guards';

const MANAGER = ['Admin', 'Manager'];

export const routes: Routes = [
  { path: 'login', loadComponent: () => import('./features/auth/login.component').then(m => m.LoginComponent) },
  {
    path: '',
    loadComponent: () => import('./layout/shell.component').then(m => m.ShellComponent),
    canActivate: [authGuard],
    children: [
      { path: '', redirectTo: 'dashboard', pathMatch: 'full' },
      { path: 'dashboard', loadComponent: () => import('./features/dashboard/dashboard.component').then(m => m.DashboardComponent) },
      { path: 'pos', loadComponent: () => import('./features/pos/pos.component').then(m => m.PosComponent) },
      { path: 'orders', loadComponent: () => import('./features/orders/orders.component').then(m => m.OrdersComponent) },
      { path: 'orders/:id', loadComponent: () => import('./features/orders/order-detail.component').then(m => m.OrderDetailComponent) },
      { path: 'food-items', loadComponent: () => import('./features/food-items/food-items.component').then(m => m.FoodItemsComponent) },
      { path: 'categories', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/categories/categories.component').then(m => m.CategoriesComponent) },
      { path: 'inventory', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/inventory/inventory.component').then(m => m.InventoryComponent) },
      { path: 'inventory/stock-in', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/inventory/stock-in.component').then(m => m.StockInComponent) },
      { path: 'inventory/transactions', loadComponent: () => import('./features/inventory/transactions.component').then(m => m.TransactionsComponent) },
      { path: 'inventory/low-stock', loadComponent: () => import('./features/inventory/low-stock.component').then(m => m.LowStockComponent) },
      { path: 'customers', loadComponent: () => import('./features/customers/customers.component').then(m => m.CustomersComponent) },
      { path: 'customers/:id', loadComponent: () => import('./features/customers/customer-detail.component').then(m => m.CustomerDetailComponent) },
      { path: 'reports/sales', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/reports/sales-report.component').then(m => m.SalesReportComponent) },
      { path: 'reports/inventory', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/reports/inventory-report.component').then(m => m.InventoryReportComponent) },
      { path: 'reports/best-selling', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/reports/best-selling.component').then(m => m.BestSellingComponent) },
      { path: 'settings', canActivate: [roleGuard], data: { roles: MANAGER }, loadComponent: () => import('./features/settings/settings.component').then(m => m.SettingsComponent) },
      { path: 'settings/users', canActivate: [roleGuard], data: { roles: ['Admin'] }, loadComponent: () => import('./features/settings/users.component').then(m => m.UsersComponent) },
    ],
  },
  { path: '**', redirectTo: '' },
];
